  <Drawer.Root open={!!phoneReview} onOpenChange={open=>{if(!open&&!phoneReviewPending)setPhoneReview(null)}} dismissible={!phoneReviewPending} shouldScaleBackground={false}><Drawer.Portal><Drawer.Overlay className="pw-overlay"/><Drawer.Content className="pw-drawer pw-scope-drawer" aria-describedby="pw-phone-description"><div className="pw-drawer-handle"/><header className="pw-drawer-header"><div><Drawer.Title>核对这次手机任务</Drawer.Title><Drawer.Description id="pw-phone-description">目标、执行位置与本次范围</Drawer.Description></div><IconButton icon={RiCloseLine} aria-label="关闭手机任务核对" disabled={phoneReviewPending} onClick={()=>setPhoneReview(null)}/></header><div className="pw-drawer-body">{phoneReview&&<PermissionReview title={phoneReview.goal} context={phoneReview.mode==='background'?'在后台独立屏执行':'在手机主屏执行'} reason={[phoneReview.message,phoneReview.screenDisclosure].filter(Boolean).join(' ')} fields={[...(phoneReview.conversationId?[{label:'结果返回',value:phoneReview.conversationTitle||'原私人对话'}]:[]),...(phoneReview.modelName?[{label:'本次模型',value:phoneReview.modelName}]:[]),{label:'工具调用上限',value:phoneReview.toolLimit},{label:'模型调用上限',value:phoneReview.modelCallLimit},{label:'本次期限',value:phoneReview.scopeMinutes<0?'使用原授权期限':phoneReview.scopeMinutes===0?'不设截止时间':`${phoneReview.scopeMinutes} 分钟`}]} onReject={phoneReviewPending?undefined:()=>setPhoneReview(null)} onApprove={can('phone.start')&&phoneStart?.status!=='unknown'?startReviewedPhone:undefined} pending={phoneReviewPending} approveLabel="开始这次任务"/>}{phoneStart&&phoneStart.status!=='accepted'&&<><Receipt receipt={phoneStart}/>{phoneStart.status==='unknown'&&(phoneStart.requestId&&phoneStart.conversationId&&can('phone.query')?<Button variant="secondary" disabled={phoneReviewPending} onClick={queryOriginalPhone}>查询原手机请求</Button>:<Button variant="secondary" onClick={()=>{setPhoneReview(null);if(phoneStart.taskId)openTask(phoneStart.taskId);else navigate('tasks')}}>核对原任务记录</Button>)}</>}</div></Drawer.Content></Drawer.Portal></Drawer.Root>
